//! Mock subgraphs for the large (ecommerce) supergraph used by the
//! `planning-large` benchmark.
//!
//! Instead of hand-writing ~80 subgraphs, every `*.graphql` file in
//! `large-graph/subgraphs` (generated by `scripts/generate-large-graph.ts`) is
//! turned into a dynamic schema whose resolvers return deterministic mock data.
//! The planning benchmark only needs the subgraphs to answer every fetch the
//! same way for the warm and the cold request, so the data itself is irrelevant.

use async_graphql::{
    dynamic::{
        Enum, EnumItem, Field, FieldFuture, FieldValue, InputValue, Interface, InterfaceField,
        Object, Schema, TypeRef, Union,
    },
    parser::{
        parse_schema,
        types::{
            BaseType, ConstDirective, FieldDefinition, Type, TypeKind, TypeSystemDefinition,
        },
    },
    Name, Positioned, Value,
};
use std::{
    collections::{BTreeMap, HashMap},
    path::PathBuf,
    sync::Arc,
};

/// Number of items returned for every list field.
const LIST_SIZE: usize = 2;

/// A mocked object. `known` holds the fields the gateway sent in an entity
/// representation (keys and `@requires` inputs), which are echoed back.
struct Node {
    index: usize,
    known: HashMap<String, Value>,
}

impl Node {
    fn new(index: usize) -> Self {
        Node {
            index,
            known: HashMap::new(),
        }
    }
}

#[derive(Clone)]
enum Leaf {
    Id,
    String,
    Int,
    Float,
    Boolean,
    Enum(String),
    Object,
    /// Interface or union: the object types it can resolve to in this subgraph.
    Abstract(Vec<String>),
}

struct Shape {
    leaf: Leaf,
    list: bool,
}

/// What the subgraph knows about its own named types.
#[derive(Default)]
struct Kinds {
    objects: Vec<String>,
    enums: HashMap<String, String>,
    possible_types: HashMap<String, Vec<String>>,
}

fn type_ref(ty: &Type) -> TypeRef {
    let inner = match &ty.base {
        BaseType::Named(name) => TypeRef::Named(name.to_string().into()),
        BaseType::List(item) => TypeRef::List(Box::new(type_ref(item))),
    };
    if ty.nullable {
        inner
    } else {
        TypeRef::NonNull(Box::new(inner))
    }
}

fn shape_of(ty: &Type, kinds: &Kinds) -> Shape {
    match &ty.base {
        BaseType::List(item) => Shape {
            leaf: shape_of(item, kinds).leaf,
            list: true,
        },
        BaseType::Named(name) => {
            let name = name.as_str();
            let leaf = match name {
                "ID" => Leaf::Id,
                "Int" => Leaf::Int,
                "Float" => Leaf::Float,
                "Boolean" => Leaf::Boolean,
                _ => {
                    if let Some(types) = kinds.possible_types.get(name) {
                        Leaf::Abstract(types.clone())
                    } else if let Some(value) = kinds.enums.get(name) {
                        Leaf::Enum(value.clone())
                    } else if kinds.objects.iter().any(|o| o == name) {
                        Leaf::Object
                    } else {
                        Leaf::String
                    }
                }
            };
            Shape { leaf, list: false }
        }
    }
}

fn mock<'a>(leaf: &Leaf, field: &str, index: usize) -> FieldValue<'a> {
    match leaf {
        Leaf::Id => FieldValue::value((index + 1).to_string()),
        Leaf::String => FieldValue::value(format!("{}-{}", field, index + 1)),
        Leaf::Int => FieldValue::value((index as i32 + 1) * 7),
        Leaf::Float => FieldValue::value((index as f64 + 1.0) * 1.5),
        Leaf::Boolean => FieldValue::value(index % 2 == 0),
        Leaf::Enum(value) => FieldValue::value(Value::Enum(Name::new(value))),
        Leaf::Object => FieldValue::owned_any(Node::new(index)),
        Leaf::Abstract(types) => {
            FieldValue::owned_any(Node::new(index)).with_type(types[index % types.len()].clone())
        }
    }
}

fn resolve<'a>(shape: &Shape, field: &str, parent: Option<&Node>) -> FieldValue<'a> {
    if shape.list {
        return FieldValue::list((0..LIST_SIZE).map(|index| mock(&shape.leaf, field, index)));
    }
    if !matches!(shape.leaf, Leaf::Object | Leaf::Abstract(_)) {
        if let Some(value) = parent.and_then(|p| p.known.get(field)) {
            return FieldValue::value(value.clone());
        }
    }
    mock(&shape.leaf, field, parent.map(|p| p.index).unwrap_or(0))
}

fn object_field(def: &FieldDefinition, kinds: &Kinds) -> Field {
    let name = def.name.node.to_string();
    let shape = Arc::new(shape_of(&def.ty.node, kinds));
    let field_name = name.clone();
    let mut field = Field::new(name, type_ref(&def.ty.node), move |ctx| {
        let parent = ctx.parent_value.try_downcast_ref::<Node>().ok();
        FieldFuture::Value(Some(resolve(&shape, &field_name, parent)))
    });
    for arg in &def.arguments {
        field = field.argument(InputValue::new(
            arg.node.name.node.to_string(),
            type_ref(&arg.node.ty.node),
        ));
    }
    field
}

fn interface_field(def: &FieldDefinition) -> InterfaceField {
    let mut field = InterfaceField::new(def.name.node.to_string(), type_ref(&def.ty.node));
    for arg in &def.arguments {
        field = field.argument(InputValue::new(
            arg.node.name.node.to_string(),
            type_ref(&arg.node.ty.node),
        ));
    }
    field
}

/// `@key(fields: "...")` selections this subgraph can resolve.
fn resolvable_keys(directives: &[Positioned<ConstDirective>]) -> Vec<String> {
    directives
        .iter()
        .filter(|d| d.node.name.node == "key")
        .filter(|d| {
            !matches!(
                d.node.get_argument("resolvable").map(|v| &v.node),
                Some(Value::Boolean(false))
            )
        })
        .filter_map(|d| match d.node.get_argument("fields").map(|v| &v.node) {
            Some(Value::String(fields)) => Some(fields.clone()),
            _ => None,
        })
        .collect()
}

fn build_schema(sdl: &str) -> Schema {
    let document = parse_schema(sdl).expect("invalid subgraph SDL");
    let types: Vec<_> = document
        .definitions
        .iter()
        .filter_map(|definition| match definition {
            TypeSystemDefinition::Type(ty) => Some(&ty.node),
            _ => None,
        })
        .collect();

    let mut kinds = Kinds::default();
    for ty in &types {
        let name = ty.name.node.to_string();
        match &ty.kind {
            TypeKind::Object(object) => {
                for interface in &object.implements {
                    kinds
                        .possible_types
                        .entry(interface.node.to_string())
                        .or_default()
                        .push(name.clone());
                }
                kinds.objects.push(name);
            }
            TypeKind::Union(union) => {
                kinds.possible_types.insert(
                    name,
                    union.members.iter().map(|m| m.node.to_string()).collect(),
                );
            }
            TypeKind::Enum(def) => {
                kinds
                    .enums
                    .insert(name, def.values[0].node.value.node.to_string());
            }
            _ => {}
        }
    }

    let mut builder = Schema::build("Query", None, None)
        .enable_federation()
        .entity_resolver(|ctx| {
            FieldFuture::new(async move {
                let representations = ctx.args.try_get("representations")?.list()?;
                let mut entities = Vec::new();
                for (index, representation) in representations.iter().enumerate() {
                    let representation = representation.object()?;
                    let type_name = representation.try_get("__typename")?.string()?.to_string();
                    let known = representation
                        .iter()
                        .map(|(name, value)| (name.to_string(), value.as_value().clone()))
                        .collect();
                    entities
                        .push(FieldValue::owned_any(Node { index, known }).with_type(type_name));
                }
                Ok(Some(FieldValue::list(entities)))
            })
        });

    let mut has_query = false;
    for ty in &types {
        let name = ty.name.node.to_string();
        match &ty.kind {
            TypeKind::Object(def) => {
                has_query |= name == "Query";
                let mut object = Object::new(name);
                for interface in &def.implements {
                    object = object.implement(interface.node.to_string());
                }
                for key in resolvable_keys(&ty.directives) {
                    object = object.key(key);
                }
                for field in &def.fields {
                    object = object.field(object_field(&field.node, &kinds));
                }
                builder = builder.register(object);
            }
            TypeKind::Interface(def) => {
                let mut interface = Interface::new(name);
                for field in &def.fields {
                    interface = interface.field(interface_field(&field.node));
                }
                builder = builder.register(interface);
            }
            TypeKind::Union(def) => {
                let mut union = Union::new(name);
                for member in &def.members {
                    union = union.possible_type(member.node.to_string());
                }
                builder = builder.register(union);
            }
            TypeKind::Enum(def) => {
                let mut item = Enum::new(name);
                for value in &def.values {
                    item = item.item(EnumItem::new(value.node.value.node.to_string()));
                }
                builder = builder.register(item);
            }
            _ => {}
        }
    }

    // Subgraphs that only contribute entity fields have no root fields.
    if !has_query {
        builder = builder.register(Object::new("Query").field(Field::new(
            "_noop",
            TypeRef::named(TypeRef::BOOLEAN),
            |_| FieldFuture::Value(Some(FieldValue::value(true))),
        )));
    }

    builder.finish().expect("invalid subgraph schema")
}

fn subgraphs_dir() -> PathBuf {
    std::env::var("LARGE_GRAPH_SUBGRAPHS_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|_| {
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../large-graph/subgraphs")
        })
}

/// One dynamic schema per generated subgraph SDL file, keyed by subgraph name.
pub fn get_subgraphs() -> BTreeMap<String, Schema> {
    let dir = subgraphs_dir();
    let Ok(entries) = std::fs::read_dir(&dir) else {
        eprintln!(
            "No large graph subgraphs found at {} (run `npm run generate-large-graph`)",
            dir.display()
        );
        return BTreeMap::new();
    };

    entries
        .flatten()
        .map(|entry| entry.path())
        .filter(|path| path.extension().is_some_and(|ext| ext == "graphql"))
        .map(|path| {
            let name = path.file_stem().unwrap().to_string_lossy().into_owned();
            let sdl = std::fs::read_to_string(&path).unwrap();
            (name, build_schema(&sdl))
        })
        .collect()
}
